<?php
namespace App\Entity;
use Doctrine\Common\Collections\ArrayCollection; use Doctrine\Common\Collections\Collection; use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity] class Circuit { #[ORM\Id,ORM\GeneratedValue,ORM\Column] private ?int $id=null; #[ORM\Column(length:150)] private string $nom=''; #[ORM\Column(length:100,nullable:true)] private ?string $pays=null; #[ORM\Column(length:100,nullable:true)] private ?string $ville=null; #[ORM\Column] private int $nombreTours=0; #[ORM\Column(type:'float',nullable:true)] private ?float $longueurTour=null; #[ORM\Column(type:'float',nullable:true)] private ?float $latitude=null; #[ORM\Column(type:'float',nullable:true)] private ?float $longitude=null; #[ORM\Column] private bool $actif=true; #[ORM\OneToMany(mappedBy:'circuit',targetEntity:Course::class)] private Collection $courses; public function __construct(){$this->courses=new ArrayCollection();} public function getId():?int{return $this->id;} public function getNom():string{return $this->nom;} public function setNom(string $v):self{$this->nom=$v;return $this;} public function getPays():?string{return $this->pays;} public function setPays(?string $v):self{$this->pays=$v;return $this;} public function getVille():?string{return $this->ville;} public function setVille(?string $v):self{$this->ville=$v;return $this;} public function getNombreTours():int{return $this->nombreTours;} public function setNombreTours(int $v):self{$this->nombreTours=$v;return $this;} public function getLongueurTour():?float{return $this->longueurTour;} public function setLongueurTour(?float $v):self{$this->longueurTour=$v;return $this;} public function getLatitude():?float{return $this->latitude;} public function setLatitude(?float $v):self{$this->latitude=$v;return $this;} public function getLongitude():?float{return $this->longitude;} public function setLongitude(?float $v):self{$this->longitude=$v;return $this;} public function isActif():bool{return $this->actif;} public function setActif(bool $v):self{$this->actif=$v;return $this;} public function getCourses():Collection{return $this->courses;} }
